export class ModelsResource {
  private readonly _client: BaseClient;

  constructor(client: BaseClient) {
    this._client = client;
  }

  /**
   * 获取当前成员可用模型清单
   * 通过登录态或外链身份一次返回对应成员完整可用模型、Provider 和有效默认模型 ID；支持内容版本协商。orderBy=custom 时按自己的团队模型、共享给我的团队模型、系统模型依次展示，各组按自定义 rank 排列；省略时保留运行时顺序，默认模型不受展示排序影响。成员展示页可通过 includeSourceMember=true 补充创建人资料，此时始终返回完整目录；外链忽略该参数
   */
  catalog(req?: ModelsCatalogReq, options?: RequestOptions): ApiPromise<ModelsCatalogRes> {
    return this._client._request<ModelsCatalogRes>({
      spec: MODELS_CATALOG_SPEC,
      rawInput: req as Record<string, unknown> | undefined,
      requestOptions: options
    });
  }

  /**
   * 获取公开系统模型
   * 返回价格页展示所需的最小化 active 系统模型与价格信息，无需鉴权
   */
  list(options?: RequestOptions): ApiPromise<ModelsListRes> {
    return this._client._request<ModelsListRes>({
      spec: MODELS_LIST_SPEC,
      requestOptions: options
    });
  }

  /**
   * 批量获取模型展示详情
   * 返回模型名称、图标、类型及当前身份或应用基线内的可用状态，不返回执行配置
   */
  summary(req: ModelsSummaryReq, options?: RequestOptions): ApiPromise<ModelsSummaryRes> {
    return this._client._request<ModelsSummaryRes>({
      spec: MODELS_SUMMARY_SPEC,
      rawInput: req as Record<string, unknown> | undefined,
      requestOptions: options
    });
  }
}

export type GeneratedResources = {
  readonly apps: AppsResource;
  readonly chat: ChatResource;
  readonly datasets: DatasetsResource;
  readonly models: ModelsResource;
};

export const createGeneratedResources = (client: BaseClient): GeneratedResources => ({
  apps: new AppsResource(client),
  chat: new ChatResource(client),
  datasets: new DatasetsResource(client),
  models: new ModelsResource(client)
});
